CREATE TABLE Warehouse (
  warehouse_id TEXT NOT NULL PRIMARY KEY,
  name TEXT NOT NULL,
  status TEXT NOT NULL,
  labor_capacity_min_per_day INTEGER NOT NULL,
  opened_date TEXT NOT NULL
);

CREATE TABLE Zone (
  zone_id TEXT NOT NULL PRIMARY KEY,
  warehouse_id TEXT NOT NULL,
  zone_type TEXT NOT NULL,
  temp_class TEXT NOT NULL,
  hazard_allowed TEXT NOT NULL,
  oversized_ok TEXT NOT NULL,
  FOREIGN KEY (warehouse_id) REFERENCES Warehouse(warehouse_id)
);

CREATE TABLE Location (
  location_id TEXT NOT NULL PRIMARY KEY,
  zone_id TEXT NOT NULL,
  warehouse_id TEXT NOT NULL,
  aisle_no INTEGER NOT NULL,
  bay_no INTEGER NOT NULL,
  level_no INTEGER NOT NULL,
  x_m REAL NOT NULL,
  y_m REAL NOT NULL,
  dock_distance_m REAL NOT NULL,
  width_cm INTEGER NOT NULL,
  depth_cm INTEGER NOT NULL,
  height_cm INTEGER NOT NULL,
  volume_cm3 INTEGER NOT NULL,
  max_weight_kg REAL NOT NULL,
  status TEXT NOT NULL,
  FOREIGN KEY (zone_id) REFERENCES Zone(zone_id),
  FOREIGN KEY (warehouse_id) REFERENCES Warehouse(warehouse_id)
);

CREATE TABLE SKU (
  sku_id TEXT NOT NULL PRIMARY KEY,
  sku_name TEXT NOT NULL,
  category TEXT NOT NULL,
  home_warehouse_id TEXT NOT NULL,
  status TEXT NOT NULL,
  created_date TEXT NOT NULL,
  FOREIGN KEY (home_warehouse_id) REFERENCES Warehouse(warehouse_id)
);

CREATE TABLE SKUProfile (
  sku_id TEXT NOT NULL PRIMARY KEY,
  length_cm REAL NOT NULL,
  width_cm REAL NOT NULL,
  height_cm REAL NOT NULL,
  weight_kg REAL NOT NULL,
  volume_cm3 INTEGER NOT NULL,
  oversized TEXT NOT NULL,
  hazard_class TEXT NOT NULL,
  temp_class TEXT NOT NULL,
  picks_total INTEGER NOT NULL,
  velocity_class TEXT NOT NULL,
  effective_from TEXT NOT NULL,
  FOREIGN KEY (sku_id) REFERENCES SKU(sku_id)
);

CREATE TABLE Order (
  order_id TEXT NOT NULL PRIMARY KEY,
  warehouse_id TEXT NOT NULL,
  order_date TEXT NOT NULL,
  shipped_date TEXT NOT NULL,
  status TEXT NOT NULL,
  total_lines INTEGER NOT NULL,
  total_units INTEGER NOT NULL,
  FOREIGN KEY (warehouse_id) REFERENCES Warehouse(warehouse_id)
);

CREATE TABLE OrderLine (
  order_line_id TEXT NOT NULL PRIMARY KEY,
  order_id TEXT NOT NULL,
  line_no INTEGER NOT NULL,
  sku_id TEXT NOT NULL,
  quantity INTEGER NOT NULL,
  FOREIGN KEY (order_id) REFERENCES Order(order_id),
  FOREIGN KEY (sku_id) REFERENCES SKU(sku_id)
);

CREATE TABLE PickEvent (
  pick_id TEXT NOT NULL PRIMARY KEY,
  order_line_id TEXT NOT NULL,
  order_id TEXT NOT NULL,
  sku_id TEXT NOT NULL,
  warehouse_id TEXT NOT NULL,
  location_id TEXT NOT NULL,
  aisle_no INTEGER NOT NULL,
  picked_at TEXT NOT NULL,
  quantity INTEGER NOT NULL,
  travel_distance_m REAL NOT NULL,
  layout TEXT NOT NULL,
  FOREIGN KEY (order_line_id) REFERENCES OrderLine(order_line_id),
  FOREIGN KEY (order_id) REFERENCES Order(order_id),
  FOREIGN KEY (sku_id) REFERENCES SKU(sku_id),
  FOREIGN KEY (warehouse_id) REFERENCES Warehouse(warehouse_id),
  FOREIGN KEY (location_id) REFERENCES Location(location_id)
);

CREATE TABLE Replenishment (
  replen_id TEXT NOT NULL PRIMARY KEY,
  warehouse_id TEXT NOT NULL,
  sku_id TEXT NOT NULL,
  location_id TEXT NOT NULL,
  replen_date TEXT NOT NULL,
  quantity INTEGER NOT NULL,
  labor_minutes REAL NOT NULL,
  trigger TEXT NOT NULL,
  status TEXT NOT NULL,
  FOREIGN KEY (warehouse_id) REFERENCES Warehouse(warehouse_id),
  FOREIGN KEY (sku_id) REFERENCES SKU(sku_id),
  FOREIGN KEY (location_id) REFERENCES Location(location_id)
);

CREATE TABLE SlotAssignment (
  slot_id TEXT NOT NULL PRIMARY KEY,
  sku_id TEXT NOT NULL,
  location_id TEXT NOT NULL,
  warehouse_id TEXT NOT NULL,
  strategy TEXT NOT NULL,
  status TEXT NOT NULL,
  effective_from TEXT NOT NULL,
  effective_to TEXT,
  FOREIGN KEY (sku_id) REFERENCES SKU(sku_id),
  FOREIGN KEY (location_id) REFERENCES Location(location_id),
  FOREIGN KEY (warehouse_id) REFERENCES Warehouse(warehouse_id)
);

CREATE TABLE AisleBlock (
  block_id TEXT NOT NULL PRIMARY KEY,
  warehouse_id TEXT NOT NULL,
  aisle_no INTEGER NOT NULL,
  blocked_from TEXT NOT NULL,
  blocked_to TEXT NOT NULL,
  reason TEXT NOT NULL,
  FOREIGN KEY (warehouse_id) REFERENCES Warehouse(warehouse_id)
);

CREATE TABLE GroundTruth (issue_id TEXT PRIMARY KEY, issue_type TEXT, entity_type TEXT, entity_id TEXT, note TEXT);












